data_dir="${DUET_DATA_DIR:-$HOME/.local/share/duet}"
for destination in "$install_dir" "$data_dir"; do
    case "$destination" in /*) ;; *) fail "DUET_INSTALL_DIR and DUET_DATA_DIR must be absolute paths" ;; esac
